export function sum(list) {
  let total = 0;
  for (let i = 1; i < list.length; i += 1) total += list[i];
  return total;
}

files.test.js:
import assert from 'node:assert';
import { sum } from './sum.js';
assert.equal(sum([1, 2, 3]), 6);
assert.equal(sum([]), 0);
console.log('ok');

